<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { cambiarEstadoDependenciaConceptoEps, guardarDependenciaConceptoEps, listarDependenciasConceptosEps, listarOpcionesDependencias } from '../services/dependenciasConceptosEps'
import type { DependenciaConceptoEps, DependenciaOption, DependenciaPayload } from '../interfaces/dependenciasConceptosEps.interface'
type EstadoFiltro='todos'|'activo'|'inactivo';type RegimenFiltro=number|'todos'|'ninguno'
const rows=ref<DependenciaConceptoEps[]>([]),conceptos=ref<DependenciaOption[]>([]),tipos=ref<DependenciaOption[]>([]),regimenes=ref<DependenciaOption[]>([]),criterio=ref(''),tipoFiltro=ref<number|'todos'>('todos'),regimenFiltro=ref<RegimenFiltro>('todos'),estadoFiltro=ref<EstadoFiltro>('todos'),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null);const form=reactive<DependenciaPayload>({concepto_padre_id:null,concepto_base_id:null,tipo_relacion_id:null,factor:null});const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
const padre=computed(()=>conceptos.value.find(x=>x.id===form.concepto_padre_id));const base=computed(()=>conceptos.value.find(x=>x.id===form.concepto_base_id));const tipo=computed(()=>tipos.value.find(x=>x.id===form.tipo_relacion_id));const sameConcept=computed(()=>form.concepto_padre_id!==null&&form.concepto_padre_id===form.concepto_base_id);const differentRegimen=computed(()=>!!padre.value&&!!base.value&&(padre.value.regimen_id??null)!==(base.value.regimen_id??null));const duplicate=computed(()=>form.concepto_padre_id!==null&&form.concepto_base_id!==null&&form.tipo_relacion_id!==null&&rows.value.some(x=>x.id!==editing.value&&x.concepto_padre_id===form.concepto_padre_id&&x.concepto_base_id===form.concepto_base_id&&x.tipo_relacion_id===form.tipo_relacion_id))
const filtered=computed(()=>{const q=criterio.value.trim().toLocaleLowerCase();return rows.value.filter(x=>{const text=`${x.concepto_padre?.codigo??''} ${x.concepto_padre?.descripcion??''} ${x.concepto_base?.codigo??''} ${x.concepto_base?.descripcion??''}`.toLocaleLowerCase();const regimes=[x.concepto_padre?.regimen_id??null,x.concepto_base?.regimen_id??null];return(!q||text.includes(q))&&(tipoFiltro.value==='todos'||x.tipo_relacion_id===tipoFiltro.value)&&(regimenFiltro.value==='todos'||(regimenFiltro.value==='ninguno'?regimes.includes(null):regimes.includes(regimenFiltro.value)))&&(estadoFiltro.value==='todos'||x.estado===(estadoFiltro.value==='activo'))})})
async function load(){loading.value=true;error.value='';try{const [items,opts]=await Promise.all([listarDependenciasConceptosEps(),listarOpcionesDependencias()]);rows.value=items;conceptos.value=opts.conceptos;tipos.value=opts.tipos_relacion;regimenes.value=opts.regimenes}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(x?:DependenciaConceptoEps){editing.value=x?.id??null;Object.assign(form,x?{concepto_padre_id:x.concepto_padre_id,concepto_base_id:x.concepto_base_id,tipo_relacion_id:x.tipo_relacion_id,factor:x.factor===null?null:Number(x.factor)}:{concepto_padre_id:null,concepto_base_id:null,tipo_relacion_id:null,factor:null});error.value='';modal.value=true}
function validate(){if(form.concepto_padre_id===null)return 'Debe seleccionar el concepto padre.';if(form.tipo_relacion_id===null)return 'Debe seleccionar el tipo de relación.';if(form.concepto_base_id===null)return 'Debe seleccionar el concepto base.';if(sameConcept.value)return 'El concepto padre debe ser diferente al concepto base.';if(differentRegimen.value)return 'El concepto base debe pertenecer al mismo régimen que el concepto padre.';if(form.factor!==null&&(!Number.isFinite(form.factor)||form.factor<0||form.factor>9999.9999))return 'El factor debe estar entre 0 y 9,999.9999.';if(duplicate.value)return 'Ya existe una dependencia con esos conceptos y tipo de relación.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarDependenciaConceptoEps(editing.value,{...form});modal.value=false;success.value=`Dependencia ${editing.value?'actualizada':'registrada'} correctamente.`;await load()}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(x:DependenciaConceptoEps){const action=x.estado?'desactivar':'restaurar';if(!confirm(`¿Desea ${action} esta dependencia?`))return;try{const r=await cambiarEstadoDependenciaConceptoEps(x.id);x.estado=r.estado;success.value=r.message??`Dependencia ${x.estado?'restaurada':'desactivada'} correctamente.`}catch(v){error.value=message(v)}}
function clear(){criterio.value='';tipoFiltro.value='todos';regimenFiltro.value='todos';estadoFiltro.value='todos'};onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Dependencias EPS</nav><header class="hero"><div class="mark">DEP</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Dependencias de conceptos EPS</h1><p>Relaciones de cálculo entre conceptos habilitados para la EPS.</p></div><strong>{{filtered.length}} de {{rows.length}}</strong><button @click="open()">+ Nueva dependencia</button></header><aside class="help"><b>Flujo de cálculo</b><span>El concepto padre se calcula usando el concepto base, el tipo de relación y un factor opcional. Ambos deben corresponder al mismo régimen.</span></aside><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="criterio" placeholder="Concepto padre o base"></label><label>Relación<select v-model="tipoFiltro"><option value="todos">Todas</option><option v-for="x in tipos" :key="x.id" :value="x.id">{{x.descripcion}}</option></select></label><label>Régimen<select v-model="regimenFiltro"><option value="todos">Todos</option><option value="ninguno">Sin régimen</option><option v-for="x in regimenes" :key="x.id" :value="x.id">{{x.descripcion}}</option></select></label><label>Estado<select v-model="estadoFiltro"><option value="todos">Todos</option><option value="activo">Activas</option><option value="inactivo">Inactivas</option></select></label><button class="soft" @click="clear">Limpiar</button></section><section class="table-card"><header><small>CADENA DE CÁLCULO</small><h2>Dependencias registradas</h2></header><div v-if="loading" class="empty">Consultando dependencias…</div><div v-else-if="!filtered.length" class="empty">No se encontraron dependencias.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Concepto padre</th><th>Relación</th><th>Concepto base</th><th>Régimen</th><th>Factor</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id"><td>{{x.id}}</td><td><b>{{x.concepto_padre?.codigo??'N/A'}}</b><small>{{x.concepto_padre?.descripcion??'Concepto no encontrado'}}</small></td><td><span class="relation">{{x.tipo_relacion?.codigo??'—'}}</span><small>{{x.tipo_relacion?.descripcion}}</small></td><td><b>{{x.concepto_base?.codigo??'N/A'}}</b><small>{{x.concepto_base?.descripcion??'Concepto no encontrado'}}</small></td><td>{{x.concepto_padre?.regimen?.descripcion??'TODOS'}}</td><td><span v-if="x.factor!==null" class="factor">{{Number(x.factor).toFixed(4)}}</span><span v-else>—</span></td><td><span :class="x.estado?'active':'inactive'">{{x.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button v-if="x.estado" class="edit" @click="open(x)">Editar</button><button :class="x.estado?'disable':'enable'" @click="toggle(x)">{{x.estado?'Desactivar':'Restaurar'}}</button></td></tr></tbody></table></div></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">DEP</div><div><small>CADENA DE CÁLCULO</small><h2>{{editing?'Editar':'Registrar'}} dependencia</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Concepto padre *<select v-model="form.concepto_padre_id"><option :value="null">Seleccione</option><option v-for="x in conceptos" :key="x.id" :value="x.id">{{x.codigo}} · {{x.descripcion}} [{{x.regimen?.descripcion??'TODOS'}}]</option></select></label><label>Tipo de relación *<select v-model="form.tipo_relacion_id"><option :value="null">Seleccione</option><option v-for="x in tipos" :key="x.id" :value="x.id">{{x.codigo}} · {{x.descripcion}}</option></select></label><label>Concepto base *<select v-model="form.concepto_base_id"><option :value="null">Seleccione</option><option v-for="x in conceptos" :key="x.id" :value="x.id">{{x.codigo}} · {{x.descripcion}} [{{x.regimen?.descripcion??'TODOS'}}]</option></select></label><label>Factor opcional<input v-model.number="form.factor" type="number" min="0" max="9999.9999" step="0.0001" placeholder="Ej. 0.1300"></label></div><p v-if="sameConcept" class="conflict">El concepto padre y el concepto base deben ser diferentes.</p><p v-else-if="differentRegimen" class="conflict">Los conceptos seleccionados pertenecen a regímenes diferentes.</p><p v-else-if="duplicate" class="conflict">Esta combinación ya está registrada.</p><aside v-if="padre&&base&&tipo" class="preview"><small>VISTA PREVIA</small><p><b>{{padre.codigo}}</b><span>→ {{tipo.codigo}} →</span><b>{{base.codigo}}</b><em v-if="form.factor!==null">× {{Number(form.factor).toFixed(4)}}</em></p></aside><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving||sameConcept||differentRegimen||duplicate">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#b15b3d;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.55rem;font-weight:800}.hero small,.table-card small,.dialog small,.preview small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#faeee9;font-size:.52rem}.hero button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.help{margin-top:10px;padding:12px 15px;display:flex;gap:9px;border-radius:8px;color:#356071;background:#eaf7fb;font-size:.56rem}.flash,.conflict{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{min-width:170px;font-size:.5rem}.filters label:first-child{margin-right:auto}.filters input,.filters select,.dialog input,.dialog select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.52rem}.soft{padding:9px;border:0;border-radius:6px;color:#64727a!important;background:#edf1f3!important;font-size:.52rem}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:1050px;border-collapse:collapse;font-size:.5rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}td>b,td>small{display:block}.active,.inactive,.relation,.factor{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.42rem}.active,.factor{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.relation{color:#315d92;background:#eaf3fb}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(880px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:8px;font-size:.5rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.preview{margin-top:14px;padding:12px;border-radius:7px;background:#f8f2ef}.preview p{margin:7px 0 0;display:flex;align-items:center;gap:10px;font-size:.56rem}.preview span{color:var(--accent)}.preview em{margin-left:auto}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:800px){.hero,.filters,.help{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%;min-width:0}.grid{grid-template-columns:1fr}.actions{min-width:140px}}
</style>
